 std::span<std::byte>write(unsigned token,std::size_t size){for(auto&r:regions)if(token>=r.token&&std::size_t(token-r.token)<=r.bytes.size()&&size<=r.bytes.size()-(token-r.token))return std::span(r.bytes).subspan(token-r.token,size);throw FormatError("Fixture write escapes owned banks");}
